# ---------------- compile check (P2): every table is built with pdflatex in a scratch directory
import subprocess, shutil, glob
CK = {}; wd = f"{WH}/work/texcheck"; os.makedirs(wd, exist_ok=True)
if shutil.which("pdflatex"):
    for f in sorted(glob.glob(f"{PK}/tables/*.tex")):
        nm = os.path.basename(f)[:-4]; open(f"{wd}/{nm}_wrap.tex", "w").write("\\documentclass{article}\\usepackage[margin=1cm,landscape]{geometry}\\begin{document}\\input{%s}\\end{document}\n" % f)
        r = subprocess.run(["pdflatex", "-interaction=nonstopmode", "-halt-on-error", f"{nm}_wrap.tex"], cwd=wd, capture_output=True, text=True, timeout=120); CK[nm] = "OK" if r.returncode == 0 else ("FAIL: " + " | ".join([l for l in r.stdout.split("\n") if l.startswith("!")][:2]))
json.dump(CK, open(f"{PK}/tables/compile_check.json", "w"), indent=1); print("tex compile:", {k: v for k, v in CK.items() if v != "OK"} or "all OK", len(CK))
